/* Fórmulas de ameaças por nível (L). Retorna stats por categoria */
function statsAmeaca(L, cat) {
  const br = L < 5 ? 0 : L < 10 ? 1 : L < 15 ? 2 : L < 20 ? 3 : L < 25 ? 4 : 6; // Bônus de Rank da faixa de nível (como os itens dos Jogadores)
  const atk = L + 2 + Math.floor(L / 2) + 2 * br;
  const reac = L + 1 + Math.floor(L / 2) + 2 * br;
  const cd = 10 + L + Math.floor(L / 3);
  const res = L + Math.floor(L / 2);
  const t = {
    'Lacaio':  { pv: 4 + 2 * L,   dano: `1d6+${L}`,                         acoes: 1,                       rd: 0 },
    'Soldado': { pv: 10 + 6 * L,  dano: `1d8+${L + Math.floor(L / 2)}`,     acoes: 1 + Math.floor(L / 10),  rd: 0 },
    'Elite':   { pv: 20 + 12 * L, dano: `2d8+${L + Math.floor(L / 2)}`,     acoes: 1 + Math.floor(L / 7),   rd: Math.floor(L / 5) },
    'Chefe':   { pv: 50 + 35 * L, dano: `3d8+${2 * L}`,                     acoes: 2 + Math.floor(L / 6),   rd: Math.floor(L / 4) }
  }[cat];
  return { atk, reac, defFixa: 10 + reac, cd, res, ...t };
}

